<?php require_once __DIR__.'/../config.php';require_admin();$metrics=['Total Orders'=>db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'Total Revenue'=>money((float)db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE payment_status='approved'")->fetchColumn()),'Pending Payments'=>db()->query("SELECT COUNT(*) FROM orders WHERE payment_status IN ('waiting_payment','waiting_verification')")->fetchColumn(),'Total Products'=>db()->query('SELECT COUNT(*) FROM products')->fetchColumn()];$recent=db()->query('SELECT o.order_number,o.total,o.payment_status,c.full_name FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC LIMIT 8')->fetchAll();$adminTitle='Dashboard overview';require __DIR__.'/_header.php';?><div class="admin-cards"><?php foreach($metrics as $label=>$v):?><article class="metric"><span class="text-xs text-slate-500 uppercase"><?=$label?></span><strong><?=e((string)$v)?></strong></article><?php endforeach;?></div><h2 class="serif text-3xl mt-10">Recent orders</h2><table class="data-table"><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th></tr><?php foreach($recent as $o):?><tr><td><b><?=e($o['order_number'])?></b></td><td><?=e($o['full_name'])?></td><td><?=money((float)$o['total'])?></td><td><span class="status"><?=e($o['payment_status'])?></span></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php'; ?>
